def build_webhook_payload(tasks: list[dict]) -> dict:
    """Build the task-sync webhook body from non-archived tasks.

    Archived tasks are never included, and all timestamps are UTC ISO-8601 with a 'Z' suffix (team policy).
    """
    return {
        "event": "tasks.sync",
        "sent_at": to_utc_iso(time.time()),
        "tasks": [
            {"id": t["id"], "title": t["title"], "due": to_utc_iso(t["due_at"])}
            for t in tasks
            if not t.get("archived")
        ],
    }


def export_webhook_payload(tasks: list[dict], out_path) -> int:
    """Write the webhook JSON body to out_path (nothing is sent). Returns the number of tasks written."""
    payload = build_webhook_payload(tasks)
    Path(out_path).write_text(json.dumps(payload, indent=2), encoding="utf-8")
    return len(payload["tasks"])


